'use client';

import { useEffect, useMemo, useState } from 'react';
import type { ChangeEvent, FormEvent, ReactNode } from 'react';
import {
  Bell, Calculator, Camera, Car, CheckCircle2, ChevronRight, ClipboardList,
  FileText, Film, ImageIcon, LayoutDashboard, LogOut, Menu, MessageCircle,
  Package, Plus, Printer, Save, Send, Settings, ShieldCheck, ShoppingCart,
  Store, Trash2, UserRound, Users, Wrench, X
} from 'lucide-react';

type AdminTab = 'dashboard' | 'requests' | 'services' | 'vehicles' | 'products' | 'showroom' | 'customers' | 'documents';
type PublicView = 'home' | 'services' | 'vehicles' | 'shop' | 'request' | 'finance' | 'admin';
type DocumentType = 'Mitsumori' | 'Invoice' | 'Seikyusho' | 'Recibo';

type Service = { id: string; name: string; subtitle: string; description: string; image: string; priceFrom?: number; active: boolean };
type Vehicle = { id: string; brand: string; model: string; year: string; mileage: string; price: number; description: string; image: string; video?: string; status: 'Disponível' | 'Reservado' | 'Vendido'; active: boolean };
type Product = { id: string; name: string; category: string; description: string; price: number; image: string; stock: number; active: boolean };
type ShowroomItem = { id: string; title: string; description: string; media: string; mediaType: 'image' | 'video'; active: boolean };
type Customer = { id: string; name: string; email: string; phone: string; vehicle?: string; createdAt: string };
type RequestItem = { id: string; type: 'Orçamento' | 'Serviço' | 'Veículo' | 'Produto'; customerName: string; email: string; phone: string; subject: string; description: string; photos: string[]; status: 'Novo' | 'Em análise' | 'Respondido' | 'Concluído'; createdAt: string };
type DocLine = { description: string; quantity: number; unitPrice: number };
type GarageDocument = { id: string; type: DocumentType; number: string; date: string; validity: string; customer: string; customerAddress: string; vehicleBrand: string; vehicleModel: string; vin: string; plate: string; engine: string; mileage: string; lines: DocLine[]; notes: string; responsible: string };

type AdminSession = { email: string } | null;

const KEY = 'yamauchi_erp_best_';
const OWNER_EMAIL = 'yamauthigaragem@gmail.com';
const shop = {
  name: 'Yamauchi Garage Auto Center',
  phone: '080-6962-8374',
  whatsapp: '818069628374',
  address: '381 Nakashinden, Fukuroi, Shizuoka 437-1111',
};

const seedServices: Service[] = [
  { id: 's1', name: 'Funilaria e Pintura', subtitle: '板金・塗装', description: 'Reparo de colisões, recuperação de painéis e pintura com acabamento profissional.', image: '/placeholder.jpg', priceFrom: 25000, active: true },
  { id: 's2', name: 'Mecânica Geral', subtitle: '一般整備', description: 'Diagnóstico, manutenção preventiva e reparos mecânicos completos.', image: '/placeholder.jpg', priceFrom: 8000, active: true },
  { id: 's3', name: 'Polimento e Cristalização', subtitle: '研磨・コーティング', description: 'Recuperação do brilho, proteção da pintura e acabamento premium.', image: '/placeholder.jpg', priceFrom: 15000, active: true },
  { id: 's4', name: 'Higienização Interna', subtitle: '車内クリーニング', description: 'Limpeza profunda de bancos, carpetes, teto e acabamento interno.', image: '/placeholder.jpg', priceFrom: 12000, active: true },
  { id: 's5', name: 'Martelinho de Ouro', subtitle: 'デントリペア', description: 'Remoção de pequenos amassados preservando a pintura original.', image: '/placeholder.jpg', priceFrom: 10000, active: true },
  { id: 's6', name: 'Som e Iluminação', subtitle: '音響・照明', description: 'Instalação de multimídia, alto-falantes, LEDs e acessórios elétricos.', image: '/placeholder.jpg', priceFrom: 10000, active: true },
];

const seedVehicles: Vehicle[] = [
  { id: 'v1', brand: 'Toyota', model: 'Prius S Touring', year: '2021', mileage: '38.000 km', price: 2380000, description: 'Híbrido econômico, revisado e pronto para entrega.', image: '/placeholder.jpg', status: 'Disponível', active: true },
  { id: 'v2', brand: 'Suzuki', model: 'Every Wagon', year: '2020', mileage: '44.000 km', price: 1280000, description: 'Kei wagon espaçoso, ideal para família e trabalho.', image: '/placeholder.jpg', status: 'Disponível', active: true },
];

const seedProducts: Product[] = [
  { id: 'p1', name: 'Kit LED Premium', category: 'Iluminação', description: 'Kit de iluminação automotiva com alto desempenho.', price: 14800, image: '/placeholder.svg', stock: 8, active: true },
  { id: 'p2', name: 'Central Multimídia', category: 'Som', description: 'Tela touch com Bluetooth, câmera e navegação.', price: 49800, image: '/placeholder.svg', stock: 4, active: true },
  { id: 'p3', name: 'Polidor Profissional', category: 'Estética', description: 'Produto para brilho e proteção da pintura.', price: 3200, image: '/placeholder.svg', stock: 15, active: true },
];

const seedShowroom: ShowroomItem[] = [
  { id: 'm1', title: 'Conheça a Yamauchi Garage', description: 'Estrutura, equipe e qualidade em cada serviço.', media: '/placeholder.jpg', mediaType: 'image', active: true },
  { id: 'm2', title: 'Antes e Depois', description: 'Veja resultados reais de funilaria e pintura.', media: '/placeholder.jpg', mediaType: 'image', active: true },
];

function load<T>(name: string, fallback: T): T {
  if (typeof window === 'undefined') return fallback;
  try { return JSON.parse(localStorage.getItem(KEY + name) || '') as T; } catch { return fallback; }
}
function persist(name: string, value: unknown) { if (typeof window !== 'undefined') localStorage.setItem(KEY + name, JSON.stringify(value)); }
function id(prefix: string) { return `${prefix}-${Date.now().toString(36)}`; }
function yen(value: number) { return `¥${Math.round(value).toLocaleString('ja-JP')}`; }
function openWhatsApp(text: string) { window.open(`https://wa.me/${shop.whatsapp}?text=${encodeURIComponent(text)}`, '_blank', 'noopener,noreferrer'); }
function imageFromFile(file: File, done: (value: string) => void) { const reader = new FileReader(); reader.onload = () => done(String(reader.result)); reader.readAsDataURL(file); }

export default function App() {
  const [view, setView] = useState<PublicView>('home');
  const [adminTab, setAdminTab] = useState<AdminTab>('dashboard');
  const [services, setServices] = useState<Service[]>(() => load('services', seedServices));
  const [vehicles, setVehicles] = useState<Vehicle[]>(() => load('vehicles', seedVehicles));
  const [products, setProducts] = useState<Product[]>(() => load('products', seedProducts));
  const [showroom, setShowroom] = useState<ShowroomItem[]>(() => load('showroom', seedShowroom));
  const [customers, setCustomers] = useState<Customer[]>(() => load('customers', []));
  const [requests, setRequests] = useState<RequestItem[]>(() => load('requests', []));
  const [documents, setDocuments] = useState<GarageDocument[]>(() => load('documents', []));
  const [admin, setAdmin] = useState<AdminSession>(null);
  const [loginOpen, setLoginOpen] = useState(false);
  const [toast, setToast] = useState('');
  const [mobileOpen, setMobileOpen] = useState(false);
  const [selectedVehicle, setSelectedVehicle] = useState<Vehicle | null>(null);
  const [selectedDocument, setSelectedDocument] = useState<GarageDocument | null>(null);

  useEffect(() => persist('services', services), [services]);
  useEffect(() => persist('vehicles', vehicles), [vehicles]);
  useEffect(() => persist('products', products), [products]);
  useEffect(() => persist('showroom', showroom), [showroom]);
  useEffect(() => persist('customers', customers), [customers]);
  useEffect(() => persist('requests', requests), [requests]);
  useEffect(() => persist('documents', documents), [documents]);

  useEffect(() => {
    fetch('/api/admin/session', { cache: 'no-store' }).then(r => r.json()).then(data => {
      if (data.authenticated) setAdmin({ email: OWNER_EMAIL });
    }).catch(() => undefined);
  }, []);

  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(''), 3500); };
  const newCount = requests.filter(r => r.status === 'Novo').length;

  async function login(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const response = await fetch('/api/admin/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email: form.get('email'), password: form.get('password') }) });
    const result = await response.json();
    if (!response.ok) return notify(result.message || 'Não foi possível entrar.');
    setAdmin({ email: OWNER_EMAIL }); setLoginOpen(false); setView('admin'); notify('Acesso administrativo liberado.');
  }
  async function logout() { await fetch('/api/admin/logout', { method: 'POST' }).catch(() => undefined); setAdmin(null); setView('home'); }

  function submitRequest(item: Omit<RequestItem, 'id' | 'status' | 'createdAt'>) {
    const request: RequestItem = { ...item, id: id('SOL'), status: 'Novo', createdAt: new Date().toLocaleString('pt-BR') };
    setRequests(prev => [request, ...prev]);
    if (!customers.some(c => c.email.toLowerCase() === item.email.toLowerCase())) {
      setCustomers(prev => [{ id: id('CLI'), name: item.customerName, email: item.email, phone: item.phone, vehicle: item.subject, createdAt: new Date().toLocaleDateString('pt-BR') }, ...prev]);
    }
    notify('Solicitação enviada com sucesso.');
    openWhatsApp(`Nova solicitação ${request.id}\nTipo: ${request.type}\nCliente: ${request.customerName}\nAssunto: ${request.subject}`);
    setView('home');
  }

  const publicServices = services.filter(s => s.active);
  const publicVehicles = vehicles.filter(v => v.active && v.status !== 'Vendido');
  const publicProducts = products.filter(p => p.active && p.stock > 0);
  const activeShowroom = showroom.filter(s => s.active);

  return <div className="min-h-screen bg-slate-50 text-slate-950">
    <Header view={view} setView={setView} admin={admin} login={() => setLoginOpen(true)} logout={logout} newCount={newCount} mobileOpen={mobileOpen} setMobileOpen={setMobileOpen} />
    {toast && <div className="fixed right-4 top-20 z-[80] rounded-xl bg-emerald-600 px-5 py-3 text-sm font-bold text-white shadow-xl">{toast}</div>}
    <main>
      {view === 'home' && <Home showroom={activeShowroom} services={publicServices} vehicles={publicVehicles} setView={setView} selectVehicle={v => { setSelectedVehicle(v); setView('finance'); }} />}
      {view === 'services' && <ServicesPage services={publicServices} request={(service) => { setView('request'); sessionStorage.setItem('yamauchi_service', service.name); }} />}
      {view === 'vehicles' && <VehiclesPage vehicles={publicVehicles} finance={vehicle => { setSelectedVehicle(vehicle); setView('finance'); }} contact={vehicle => openWhatsApp(`Olá! Tenho interesse no veículo ${vehicle.brand} ${vehicle.model}.`)} />}
      {view === 'shop' && <ShopPage products={publicProducts} interest={product => { submitRequest({ type: 'Produto', customerName: 'Cliente interessado', email: '', phone: '', subject: product.name, description: `Interesse no produto ${product.name}`, photos: [] }); }} />}
      {view === 'request' && <RequestPage services={publicServices} submit={submitRequest} />}
      {view === 'finance' && <FinancePage vehicle={selectedVehicle} back={() => setView('vehicles')} contact={() => selectedVehicle && openWhatsApp(`Olá! Gostaria de consultar financiamento para ${selectedVehicle.brand} ${selectedVehicle.model}.`)} />}
      {view === 'admin' && admin && <AdminPanel tab={adminTab} setTab={setAdminTab} services={services} setServices={setServices} vehicles={vehicles} setVehicles={setVehicles} products={products} setProducts={setProducts} showroom={showroom} setShowroom={setShowroom} customers={customers} setCustomers={setCustomers} requests={requests} setRequests={setRequests} documents={documents} setDocuments={setDocuments} selectDocument={setSelectedDocument} />}
      {selectedDocument && <DocumentPrint document={selectedDocument} close={() => setSelectedDocument(null)} />}
    </main>
    {loginOpen && <LoginModal close={() => setLoginOpen(false)} login={login} />}
    <footer className="border-t bg-slate-950 py-10 text-white print:hidden"><div className="mx-auto grid max-w-6xl gap-6 px-5 md:grid-cols-3"><div><p className="text-xl font-black text-amber-400">YAMAUCHI GARAGE</p><p className="text-xs tracking-[.25em]">AUTO CENTER · SINCE 2016</p></div><div className="text-sm"><p>{shop.address}</p><p>{shop.phone}</p></div><button onClick={() => openWhatsApp('Olá Yamauchi Garage!')} className="rounded-xl bg-emerald-600 px-5 py-3 font-black"><MessageCircle className="mr-2 inline h-5 w-5" />WhatsApp</button></div></footer>
  </div>;
}

function Header({ view, setView, admin, login, logout, newCount, mobileOpen, setMobileOpen }: { view: PublicView; setView: (v: PublicView) => void; admin: AdminSession; login: () => void; logout: () => void; newCount: number; mobileOpen: boolean; setMobileOpen: (v: boolean) => void }) {
  const links: [PublicView, string][] = [['home','Início'],['services','Serviços'],['vehicles','Carros à venda'],['shop','Loja']];
  return <header className="sticky top-0 z-50 bg-slate-950 text-white shadow-lg print:hidden"><div className="mx-auto flex h-20 max-w-7xl items-center justify-between px-5"><button onClick={() => setView('home')} className="flex items-center gap-3 text-left"><img src="/yamauchi-logo.png" alt="Yamauchi Garage" className="h-12 w-12 rounded-xl object-contain"/><div><p className="font-black text-amber-400">山内ガレージ 板金</p><p className="text-[10px] font-bold tracking-[.28em]">YAMAUCHI GARAGE AUTO CENTER</p></div></button><nav className="hidden items-center gap-6 lg:flex">{links.map(([key,label]) => <button key={key} onClick={() => setView(key)} className={`text-sm font-bold ${view===key?'text-amber-400':'hover:text-amber-300'}`}>{label}</button>)}<button onClick={() => setView('request')} className="rounded-xl bg-amber-400 px-4 py-2 text-sm font-black text-slate-950">Solicitar orçamento</button>{admin ? <><button onClick={() => setView('admin')} className="relative rounded-xl bg-blue-700 px-4 py-2 text-sm font-black"><ShieldCheck className="mr-1 inline h-4 w-4"/>Admin{newCount>0&&<span className="absolute -right-2 -top-2 rounded-full bg-red-600 px-2 py-0.5 text-[10px]">{newCount}</span>}</button><button onClick={logout}><LogOut className="h-5 w-5"/></button></> : <button onClick={login} className="rounded-xl border border-white/20 px-4 py-2 text-sm font-bold"><UserRound className="mr-1 inline h-4 w-4"/>Entrar</button>}</nav><button className="lg:hidden" onClick={() => setMobileOpen(!mobileOpen)}>{mobileOpen?<X/>:<Menu/>}</button></div>{mobileOpen&&<div className="border-t border-white/10 px-5 py-4 lg:hidden">{links.map(([key,label]) => <button key={key} onClick={() => {setView(key);setMobileOpen(false);}} className="block w-full py-3 text-left font-bold">{label}</button>)}<button onClick={() => {setView('request');setMobileOpen(false);}} className="block w-full py-3 text-left font-bold text-amber-400">Solicitar orçamento</button><button onClick={() => {admin?setView('admin'):login();setMobileOpen(false);}} className="block w-full py-3 text-left font-bold">{admin?'Painel Admin':'Entrar'}</button></div>}</header>;
}

function Home({ showroom, services, vehicles, setView, selectVehicle }: { showroom: ShowroomItem[]; services: Service[]; vehicles: Vehicle[]; setView: (v: PublicView)=>void; selectVehicle:(v:Vehicle)=>void }) {
  return <div><section className="bg-gradient-to-br from-slate-950 via-blue-950 to-blue-900 text-white"><div className="mx-auto grid max-w-7xl gap-10 px-5 py-20 lg:grid-cols-[1.1fr_.9fr] lg:items-center"><div><p className="mb-4 text-sm font-black tracking-[.25em] text-amber-400">AUTO CENTER NO JAPÃO</p><h1 className="text-5xl font-black leading-tight md:text-7xl">Seu carro, nosso padrão de excelência.</h1><p className="mt-6 max-w-2xl text-lg text-blue-100">Serviços automotivos, veículos selecionados, acessórios e pré-avaliação por fotos em um só lugar.</p><div className="mt-8 flex flex-wrap gap-3"><button onClick={()=>setView('request')} className="rounded-xl bg-amber-400 px-6 py-4 font-black text-slate-950">SOLICITAR PRÉ-AVALIAÇÃO</button><button onClick={()=>setView('vehicles')} className="rounded-xl border border-white/30 px-6 py-4 font-black">VER CARROS À VENDA</button></div></div><div className="rounded-[2rem] border border-white/10 bg-white/5 p-4 backdrop-blur"><img src="/yamauchi-logo.png" alt="Yamauchi Garage" className="mx-auto h-80 w-full object-contain"/></div></div></section>
    <section className="mx-auto max-w-7xl px-5 py-16"><SectionTitle kicker="SHOWROOM" title="Conheça nosso trabalho" action="Atualizado pelo painel administrativo"/><div className="grid gap-5 md:grid-cols-2">{showroom.map(item=><article key={item.id} className="overflow-hidden rounded-3xl bg-slate-950 text-white shadow-xl">{item.mediaType==='video'?<video controls className="h-72 w-full object-cover" src={item.media}/>:<img src={item.media} alt={item.title} className="h-72 w-full object-cover"/>}<div className="p-6"><h3 className="text-2xl font-black">{item.title}</h3><p className="mt-2 text-slate-300">{item.description}</p></div></article>)}</div></section>
    <section className="bg-white py-16"><div className="mx-auto max-w-7xl px-5"><SectionTitle kicker="SERVIÇOS" title="Tudo o que seu veículo precisa" actionButton="Ver todos" onAction={()=>setView('services')}/><div className="grid gap-5 md:grid-cols-2 lg:grid-cols-3">{services.slice(0,6).map(service=><ServiceCard key={service.id} service={service}/>)}</div></div></section>
    <section className="mx-auto max-w-7xl px-5 py-16"><SectionTitle kicker="VEÍCULOS" title="Carros selecionados à venda" actionButton="Ver estoque" onAction={()=>setView('vehicles')}/><div className="grid gap-6 md:grid-cols-2">{vehicles.slice(0,2).map(vehicle=><VehicleCard key={vehicle.id} vehicle={vehicle} finance={()=>selectVehicle(vehicle)} contact={()=>openWhatsApp(`Olá! Tenho interesse no ${vehicle.brand} ${vehicle.model}.`)}/>)}</div></section>
  </div>;
}

function SectionTitle({ kicker, title, action, actionButton, onAction }: { kicker:string; title:string; action?:string; actionButton?:string; onAction?:()=>void }) { return <div className="mb-8 flex flex-wrap items-end justify-between gap-4"><div><p className="text-sm font-black tracking-[.2em] text-amber-600">{kicker}</p><h2 className="mt-2 text-3xl font-black md:text-4xl">{title}</h2></div>{action&&<p className="text-sm text-slate-500">{action}</p>}{actionButton&&<button onClick={onAction} className="font-black text-blue-900">{actionButton}<ChevronRight className="inline h-4 w-4"/></button>}</div>; }
function ServiceCard({ service }: { service: Service }) { return <article className="group overflow-hidden rounded-3xl border bg-white shadow-sm transition hover:-translate-y-1 hover:shadow-xl"><img src={service.image} alt={service.name} className="h-48 w-full object-cover"/><div className="p-6"><p className="text-xs font-black text-amber-600">{service.subtitle}</p><h3 className="mt-2 text-xl font-black">{service.name}</h3><p className="mt-3 text-sm leading-6 text-slate-600">{service.description}</p>{service.priceFrom&&<p className="mt-4 font-black text-blue-900">A partir de {yen(service.priceFrom)}</p>}</div></article>; }

function ServicesPage({ services, request }: { services:Service[]; request:(s:Service)=>void }) { return <section className="mx-auto max-w-7xl px-5 py-14"><SectionTitle kicker="SERVIÇOS" title="Escolha visualmente o serviço desejado" action="Clique no serviço para solicitar avaliação"/><div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">{services.map(service=><article key={service.id} className="overflow-hidden rounded-3xl border bg-white shadow-sm"><img src={service.image} alt={service.name} className="h-56 w-full object-cover"/><div className="p-6"><p className="text-xs font-black text-amber-600">{service.subtitle}</p><h2 className="mt-1 text-2xl font-black">{service.name}</h2><p className="mt-3 text-slate-600">{service.description}</p><button onClick={()=>request(service)} className="mt-5 w-full rounded-xl bg-blue-950 py-3 font-black text-white">SOLICITAR PRÉ-AVALIAÇÃO</button></div></article>)}</div></section>; }

function VehicleCard({ vehicle, finance, contact }: { vehicle:Vehicle; finance:()=>void; contact:()=>void }) { return <article className="overflow-hidden rounded-3xl border bg-white shadow-sm"><div className="relative"><img src={vehicle.image} alt={`${vehicle.brand} ${vehicle.model}`} className="h-72 w-full object-cover"/><span className="absolute left-4 top-4 rounded-full bg-emerald-600 px-3 py-1 text-xs font-black text-white">{vehicle.status}</span></div><div className="p-6"><p className="text-sm font-bold text-slate-500">{vehicle.year} · {vehicle.mileage}</p><h3 className="mt-1 text-2xl font-black">{vehicle.brand} {vehicle.model}</h3><p className="mt-3 text-slate-600">{vehicle.description}</p><p className="mt-5 text-3xl font-black text-blue-950">{yen(vehicle.price)}</p><div className="mt-5 grid grid-cols-2 gap-3"><button onClick={finance} className="rounded-xl bg-amber-400 py-3 text-sm font-black">SIMULAR FINANCIAMENTO</button><button onClick={contact} className="rounded-xl bg-emerald-600 py-3 text-sm font-black text-white">WHATSAPP</button></div></div></article>; }
function VehiclesPage({ vehicles, finance, contact }: { vehicles:Vehicle[]; finance:(v:Vehicle)=>void; contact:(v:Vehicle)=>void }) { return <section className="mx-auto max-w-7xl px-5 py-14"><SectionTitle kicker="ESTOQUE" title="Veículos à venda" action="Valores e disponibilidade podem ser atualizados pelo administrador"/><div className="grid gap-6 md:grid-cols-2">{vehicles.map(v=><VehicleCard key={v.id} vehicle={v} finance={()=>finance(v)} contact={()=>contact(v)}/>)}</div></section>; }

function FinancePage({ vehicle, back, contact }: { vehicle:Vehicle|null; back:()=>void; contact:()=>void }) {
  const [entry, setEntry] = useState(vehicle ? Math.round(vehicle.price*.2) : 300000);
  const [months, setMonths] = useState(60); const [rate, setRate] = useState(4.9);
  const principal = Math.max(0,(vehicle?.price||0)-entry); const monthlyRate=rate/100/12; const payment=monthlyRate===0?principal/months:principal*(monthlyRate*Math.pow(1+monthlyRate,months))/(Math.pow(1+monthlyRate,months)-1);
  return <section className="mx-auto max-w-5xl px-5 py-14"><button onClick={back} className="mb-5 font-bold text-blue-900">← Voltar aos veículos</button><div className="grid gap-6 lg:grid-cols-2"><div className="rounded-3xl bg-slate-950 p-7 text-white"><Calculator className="h-10 w-10 text-amber-400"/><h1 className="mt-4 text-3xl font-black">Simulação de financiamento</h1><p className="mt-3 text-slate-300">{vehicle?`${vehicle.brand} ${vehicle.model}`:'Selecione um veículo'}</p><p className="mt-6 text-4xl font-black text-amber-400">{yen(vehicle?.price||0)}</p><div className="mt-8 space-y-4"><label className="block text-sm font-bold">Entrada<input type="number" value={entry} onChange={e=>setEntry(Number(e.target.value))} className="input mt-2 text-slate-950"/></label><label className="block text-sm font-bold">Parcelas<select value={months} onChange={e=>setMonths(Number(e.target.value))} className="input mt-2 text-slate-950"><option value={24}>24 meses</option><option value={36}>36 meses</option><option value={48}>48 meses</option><option value={60}>60 meses</option><option value={72}>72 meses</option><option value={84}>84 meses</option></select></label><label className="block text-sm font-bold">Taxa anual estimada (%)<input type="number" step="0.1" value={rate} onChange={e=>setRate(Number(e.target.value))} className="input mt-2 text-slate-950"/></label></div></div><div className="rounded-3xl border bg-white p-7"><p className="text-sm font-black text-amber-600">RESULTADO ESTIMADO</p><p className="mt-5 text-slate-500">Valor financiado</p><p className="text-3xl font-black">{yen(principal)}</p><p className="mt-7 text-slate-500">Parcela aproximada</p><p className="text-5xl font-black text-blue-950">{yen(Number.isFinite(payment)?payment:0)}</p><p className="mt-8 rounded-xl bg-amber-50 p-4 text-sm leading-6 text-amber-900">Esta é somente uma simulação. Os valores, juros, prazos e aprovação podem mudar conforme análise de crédito e condições da instituição financeira.</p><button onClick={contact} className="mt-6 w-full rounded-xl bg-emerald-600 py-4 font-black text-white">CONSULTAR PELO WHATSAPP</button></div></div></section>;
}

function ShopPage({ products, interest }: { products:Product[]; interest:(p:Product)=>void }) { return <section className="mx-auto max-w-7xl px-5 py-14"><SectionTitle kicker="LOJA AUTOMOTIVA" title="Peças, acessórios, som e iluminação" action="Produtos com foto e disponibilidade atualizadas pelo administrador"/><div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3">{products.map(p=><article key={p.id} className="overflow-hidden rounded-3xl border bg-white"><img src={p.image} alt={p.name} className="h-52 w-full object-contain bg-slate-100 p-4"/><div className="p-5"><p className="text-xs font-black text-amber-600">{p.category}</p><h3 className="mt-1 text-xl font-black">{p.name}</h3><p className="mt-2 text-sm text-slate-600">{p.description}</p><div className="mt-5 flex items-center justify-between"><p className="text-2xl font-black text-blue-950">{yen(p.price)}</p><p className="text-xs font-bold text-slate-500">Estoque: {p.stock}</p></div><button onClick={()=>interest(p)} className="mt-5 w-full rounded-xl bg-blue-950 py-3 font-black text-white">TENHO INTERESSE</button></div></article>)}</div></section>; }

function RequestPage({ services, submit }: { services:Service[]; submit:(r:Omit<RequestItem,'id'|'status'|'createdAt'>)=>void }) {
  const [photos,setPhotos]=useState<string[]>([]);
  function onSubmit(event:FormEvent<HTMLFormElement>){event.preventDefault();const f=new FormData(event.currentTarget);submit({type:'Orçamento',customerName:String(f.get('name')),email:String(f.get('email')),phone:String(f.get('phone')),subject:String(f.get('vehicle')),description:`Serviço: ${f.get('service')}\n${f.get('description')}`,photos});}
  function upload(e:ChangeEvent<HTMLInputElement>){Array.from(e.target.files||[]).slice(0,6-photos.length).forEach(file=>imageFromFile(file,v=>setPhotos(prev=>[...prev,v])));}
  return <section className="mx-auto max-w-4xl px-5 py-14"><div className="rounded-3xl border bg-white p-7 shadow-sm"><SectionTitle kicker="PRÉ-AVALIAÇÃO" title="Envie os dados e fotos do veículo" action="A equipe responderá com uma avaliação inicial"/><form onSubmit={onSubmit} className="grid gap-4 md:grid-cols-2"><input required name="name" placeholder="Nome completo" className="input"/><input required name="phone" placeholder="Telefone / WhatsApp" className="input"/><input required type="email" name="email" placeholder="E-mail" className="input"/><input required name="vehicle" placeholder="Marca, modelo e ano do veículo" className="input"/><select name="service" className="input md:col-span-2">{services.map(s=><option key={s.id}>{s.name}</option>)}</select><textarea required name="description" placeholder="Descreva o problema, dano ou serviço desejado" className="input min-h-32 md:col-span-2"/><label className="cursor-pointer rounded-2xl border-2 border-dashed p-5 text-center font-bold text-slate-500 md:col-span-2"><Camera className="mx-auto mb-2"/>Adicionar até 6 fotos<input type="file" multiple accept="image/*" className="hidden" onChange={upload}/></label>{photos.length>0&&<div className="grid grid-cols-3 gap-3 md:col-span-2">{photos.map((p,i)=><img key={i} src={p} alt="Foto enviada" className="h-28 w-full rounded-xl object-cover"/>)}</div>}<button className="rounded-xl bg-amber-400 py-4 font-black md:col-span-2">ENVIAR SOLICITAÇÃO</button></form></div></section>;
}

function LoginModal({ close, login }: { close:()=>void; login:(e:FormEvent<HTMLFormElement>)=>void }) { return <div className="fixed inset-0 z-[100] grid place-items-center bg-slate-950/70 p-4"><form onSubmit={login} className="w-full max-w-md rounded-3xl bg-white p-7 shadow-2xl"><div className="flex items-center justify-between"><div><p className="text-sm font-black text-amber-600">ACESSO RESTRITO</p><h2 className="text-2xl font-black">Administrador</h2></div><button type="button" onClick={close}><X/></button></div><input name="email" type="email" defaultValue={OWNER_EMAIL} className="input mt-6"/><input name="password" type="password" placeholder="Senha administrativa" className="input mt-3"/><button className="mt-4 w-full rounded-xl bg-blue-950 py-4 font-black text-white">ENTRAR COMO ADMINISTRADOR</button></form></div>; }

function AdminPanel(props: { tab:AdminTab; setTab:(t:AdminTab)=>void; services:Service[]; setServices:(v:Service[])=>void; vehicles:Vehicle[]; setVehicles:(v:Vehicle[])=>void; products:Product[]; setProducts:(v:Product[])=>void; showroom:ShowroomItem[]; setShowroom:(v:ShowroomItem[])=>void; customers:Customer[]; setCustomers:(v:Customer[])=>void; requests:RequestItem[]; setRequests:(v:RequestItem[])=>void; documents:GarageDocument[]; setDocuments:(v:GarageDocument[])=>void; selectDocument:(v:GarageDocument)=>void }) {
  const tabs:[AdminTab,string,ReactNode][]=[['dashboard','Dashboard',<LayoutDashboard key="i"/>],['requests','Solicitações',<Bell key="i"/>],['services','Serviços',<Wrench key="i"/>],['vehicles','Veículos',<Car key="i"/>],['products','Produtos',<Package key="i"/>],['showroom','Showroom',<Film key="i"/>],['customers','Clientes',<Users key="i"/>],['documents','Documentos',<FileText key="i"/>]];
  return <section className="mx-auto max-w-[1500px] px-4 py-8"><div className="grid gap-6 lg:grid-cols-[240px_1fr]"><aside className="h-fit rounded-3xl bg-slate-950 p-4 text-white"><p className="px-3 py-3 text-sm font-black text-amber-400">PAINEL ADMINISTRATIVO</p>{tabs.map(([key,label,icon])=><button key={key} onClick={()=>props.setTab(key)} className={`mb-1 flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-bold ${props.tab===key?'bg-amber-400 text-slate-950':'hover:bg-white/10'}`}><span className="[&>svg]:h-5 [&>svg]:w-5">{icon}</span>{label}</button>)}</aside><div>
    {props.tab==='dashboard'&&<AdminDashboard {...props}/>} {props.tab==='requests'&&<RequestsManager requests={props.requests} setRequests={props.setRequests}/>} {props.tab==='services'&&<ServicesManager items={props.services} setItems={props.setServices}/>} {props.tab==='vehicles'&&<VehiclesManager items={props.vehicles} setItems={props.setVehicles}/>} {props.tab==='products'&&<ProductsManager items={props.products} setItems={props.setProducts}/>} {props.tab==='showroom'&&<ShowroomManager items={props.showroom} setItems={props.setShowroom}/>} {props.tab==='customers'&&<CustomersManager items={props.customers} setItems={props.setCustomers}/>} {props.tab==='documents'&&<DocumentsManager items={props.documents} setItems={props.setDocuments} select={props.selectDocument}/>} 
  </div></div></section>;
}
function AdminDashboard(p:{requests:RequestItem[];customers:Customer[];vehicles:Vehicle[];products:Product[];documents:GarageDocument[]}){const cards=[['Novas solicitações',p.requests.filter(r=>r.status==='Novo').length],['Clientes',p.customers.length],['Veículos publicados',p.vehicles.filter(v=>v.active).length],['Produtos ativos',p.products.filter(v=>v.active).length],['Documentos',p.documents.length]];return <div><SectionTitle kicker="VISÃO GERAL" title="Controle total da Yamauchi Garage" action="Todas as alterações são feitas aqui"/><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5">{cards.map(([label,value])=><div key={String(label)} className="rounded-2xl border bg-white p-5"><p className="text-sm text-slate-500">{label}</p><p className="mt-2 text-4xl font-black text-blue-950">{value}</p></div>)}</div><div className="mt-6 rounded-3xl bg-gradient-to-r from-slate-950 to-blue-950 p-8 text-white"><h2 className="text-2xl font-black">Sistema pronto para administrar conteúdo</h2><p className="mt-2 text-slate-300">Adicione ou remova serviços, veículos, produtos, vídeos, clientes e documentos sem editar código.</p></div></div>}

function RequestsManager({requests,setRequests}:{requests:RequestItem[];setRequests:(v:RequestItem[])=>void}){return <ManagerShell title="Solicitações e alertas" subtitle="Orçamentos, serviços, veículos e produtos recebidos"><div className="space-y-4">{requests.length===0?<Empty text="Nenhuma solicitação recebida."/>:requests.map(r=><article key={r.id} className="rounded-2xl border bg-white p-5"><div className="flex flex-wrap justify-between gap-3"><div><p className="text-xs font-black text-amber-600">{r.type} · {r.id}</p><h3 className="text-xl font-black">{r.customerName}</h3><p className="text-sm text-slate-500">{r.phone} · {r.email} · {r.createdAt}</p><p className="mt-2 font-bold">{r.subject}</p><p className="mt-2 whitespace-pre-line text-sm text-slate-600">{r.description}</p></div><select value={r.status} onChange={e=>setRequests(requests.map(x=>x.id===r.id?{...x,status:e.target.value as RequestItem['status']}:x))} className="input h-fit max-w-48"><option>Novo</option><option>Em análise</option><option>Respondido</option><option>Concluído</option></select></div>{r.photos.length>0&&<div className="mt-4 flex flex-wrap gap-2">{r.photos.map((p,i)=><img key={i} src={p} alt="Foto" className="h-24 w-32 rounded-xl object-cover"/>)}</div>}<div className="mt-4 flex gap-2"><button onClick={()=>openWhatsApp(`Olá ${r.customerName}, sobre sua solicitação ${r.id}: `)} className="rounded-xl bg-emerald-600 px-4 py-2 text-sm font-black text-white"><MessageCircle className="mr-1 inline h-4 w-4"/>Responder</button><button onClick={()=>setRequests(requests.filter(x=>x.id!==r.id))} className="rounded-xl bg-red-50 px-4 py-2 text-sm font-black text-red-700"><Trash2 className="mr-1 inline h-4 w-4"/>Excluir</button></div></article>)}</div></ManagerShell>}

function ServicesManager({items,setItems}:{items:Service[];setItems:(v:Service[])=>void}){const blank={name:'',subtitle:'',description:'',image:'',priceFrom:''};const [form,setForm]=useState(blank);function add(){if(!form.name)return;setItems([{id:id('SER'),name:form.name,subtitle:form.subtitle,description:form.description,image:form.image||'/placeholder.jpg',priceFrom:Number(form.priceFrom)||undefined,active:true},...items]);setForm(blank);}return <ManagerShell title="Gerenciar serviços" subtitle="Adicione, edite visibilidade ou exclua serviços"><EditorGrid><EditorCard title="Novo serviço"><input className="input" placeholder="Nome" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/><input className="input" placeholder="Nome em japonês" value={form.subtitle} onChange={e=>setForm({...form,subtitle:e.target.value})}/><textarea className="input" placeholder="Descrição" value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/><input className="input" type="number" placeholder="Preço inicial em ienes" value={form.priceFrom} onChange={e=>setForm({...form,priceFrom:e.target.value})}/><FileField label="Foto do serviço" value={form.image} setValue={v=>setForm({...form,image:v})}/><PrimaryButton onClick={add}>PUBLICAR SERVIÇO</PrimaryButton></EditorCard><ListCard items={items} render={(s)=><ContentRow key={s.id} image={s.image} title={s.name} subtitle={s.subtitle} active={s.active} toggle={()=>setItems(items.map(x=>x.id===s.id?{...x,active:!x.active}:x))} remove={()=>confirm('Excluir este serviço?')&&setItems(items.filter(x=>x.id!==s.id))}/>} /></EditorGrid></ManagerShell>}
function VehiclesManager({items,setItems}:{items:Vehicle[];setItems:(v:Vehicle[])=>void}){const blank={brand:'',model:'',year:'',mileage:'',price:'',description:'',image:'',video:''};const [f,setF]=useState(blank);function add(){if(!f.brand||!f.model||!Number(f.price))return;setItems([{id:id('CAR'),brand:f.brand,model:f.model,year:f.year,mileage:f.mileage,price:Number(f.price),description:f.description,image:f.image||'/placeholder.jpg',video:f.video,status:'Disponível',active:true},...items]);setF(blank);}return <ManagerShell title="Carros à venda" subtitle="Publique veículos produzidos pela empresa e controle disponibilidade"><EditorGrid><EditorCard title="Novo veículo"><div className="grid grid-cols-2 gap-3"><input className="input" placeholder="Marca" value={f.brand} onChange={e=>setF({...f,brand:e.target.value})}/><input className="input" placeholder="Modelo" value={f.model} onChange={e=>setF({...f,model:e.target.value})}/><input className="input" placeholder="Ano" value={f.year} onChange={e=>setF({...f,year:e.target.value})}/><input className="input" placeholder="Quilometragem" value={f.mileage} onChange={e=>setF({...f,mileage:e.target.value})}/></div><input className="input" type="number" placeholder="Preço em ienes" value={f.price} onChange={e=>setF({...f,price:e.target.value})}/><textarea className="input" placeholder="Descrição" value={f.description} onChange={e=>setF({...f,description:e.target.value})}/><FileField label="Foto principal" value={f.image} setValue={v=>setF({...f,image:v})}/><input className="input" placeholder="URL do vídeo (opcional)" value={f.video} onChange={e=>setF({...f,video:e.target.value})}/><PrimaryButton onClick={add}>PUBLICAR VEÍCULO</PrimaryButton></EditorCard><ListCard items={items} render={(v)=><div key={v.id} className="rounded-2xl border p-4"><ContentRow image={v.image} title={`${v.brand} ${v.model}`} subtitle={`${v.year} · ${yen(v.price)}`} active={v.active} toggle={()=>setItems(items.map(x=>x.id===v.id?{...x,active:!x.active}:x))} remove={()=>confirm('Excluir este veículo?')&&setItems(items.filter(x=>x.id!==v.id))}/><select className="input mt-3" value={v.status} onChange={e=>setItems(items.map(x=>x.id===v.id?{...x,status:e.target.value as Vehicle['status']}:x))}><option>Disponível</option><option>Reservado</option><option>Vendido</option></select></div>} /></EditorGrid></ManagerShell>}
function ProductsManager({items,setItems}:{items:Product[];setItems:(v:Product[])=>void}){const blank={name:'',category:'',description:'',price:'',stock:'',image:''};const[f,setF]=useState(blank);function add(){if(!f.name||!Number(f.price))return;setItems([{id:id('PRO'),name:f.name,category:f.category,description:f.description,price:Number(f.price),stock:Number(f.stock)||0,image:f.image||'/placeholder.svg',active:true},...items]);setF(blank);}return <ManagerShell title="Peças e acessórios" subtitle="Cadastre fotos, estoque e remova itens indisponíveis"><EditorGrid><EditorCard title="Novo produto"><input className="input" placeholder="Nome" value={f.name} onChange={e=>setF({...f,name:e.target.value})}/><input className="input" placeholder="Categoria" value={f.category} onChange={e=>setF({...f,category:e.target.value})}/><textarea className="input" placeholder="Descrição" value={f.description} onChange={e=>setF({...f,description:e.target.value})}/><div className="grid grid-cols-2 gap-3"><input className="input" type="number" placeholder="Preço" value={f.price} onChange={e=>setF({...f,price:e.target.value})}/><input className="input" type="number" placeholder="Estoque" value={f.stock} onChange={e=>setF({...f,stock:e.target.value})}/></div><FileField label="Foto do produto" value={f.image} setValue={v=>setF({...f,image:v})}/><PrimaryButton onClick={add}>PUBLICAR PRODUTO</PrimaryButton></EditorCard><ListCard items={items} render={(p)=><div key={p.id} className="rounded-2xl border p-4"><ContentRow image={p.image} title={p.name} subtitle={`${yen(p.price)} · Estoque ${p.stock}`} active={p.active} toggle={()=>setItems(items.map(x=>x.id===p.id?{...x,active:!x.active}:x))} remove={()=>confirm('Excluir este produto?')&&setItems(items.filter(x=>x.id!==p.id))}/><input type="number" className="input mt-3" value={p.stock} onChange={e=>setItems(items.map(x=>x.id===p.id?{...x,stock:Number(e.target.value)}:x))}/></div>} /></EditorGrid></ManagerShell>}
function ShowroomManager({items,setItems}:{items:ShowroomItem[];setItems:(v:ShowroomItem[])=>void}){const blank={title:'',description:'',media:'',mediaType:'image' as const};const[f,setF]=useState(blank);function add(){if(!f.title||!f.media)return;setItems([{id:id('MID'),...f,active:true},...items]);setF(blank);}return <ManagerShell title="Showroom da página inicial" subtitle="Atualize vídeos, imagens e apresentações continuamente"><EditorGrid><EditorCard title="Nova mídia"><input className="input" placeholder="Título" value={f.title} onChange={e=>setF({...f,title:e.target.value})}/><textarea className="input" placeholder="Descrição" value={f.description} onChange={e=>setF({...f,description:e.target.value})}/><select className="input" value={f.mediaType} onChange={e=>setF({...f,mediaType:e.target.value as 'image'|'video'})}><option value="image">Imagem</option><option value="video">Vídeo</option></select>{f.mediaType==='image'?<FileField label="Imagem" value={f.media} setValue={v=>setF({...f,media:v})}/>:<><input className="input" placeholder="URL ou arquivo de vídeo" value={f.media} onChange={e=>setF({...f,media:e.target.value})}/><label className="block cursor-pointer rounded-xl border-2 border-dashed p-4 text-center text-sm font-bold">Selecionar vídeo<input className="hidden" type="file" accept="video/*" onChange={e=>{const file=e.target.files?.[0];if(file)imageFromFile(file,v=>setF({...f,media:v}))}}/></label></>}<PrimaryButton onClick={add}>PUBLICAR NO SHOWROOM</PrimaryButton></EditorCard><ListCard items={items} render={(m)=><ContentRow key={m.id} image={m.mediaType==='image'?m.media:'/placeholder.svg'} title={m.title} subtitle={m.mediaType==='video'?'Vídeo':'Imagem'} active={m.active} toggle={()=>setItems(items.map(x=>x.id===m.id?{...x,active:!x.active}:x))} remove={()=>confirm('Excluir esta mídia?')&&setItems(items.filter(x=>x.id!==m.id))}/>} /></EditorGrid></ManagerShell>}
function CustomersManager({items,setItems}:{items:Customer[];setItems:(v:Customer[])=>void}){return <ManagerShell title="Clientes cadastrados" subtitle="Edite ou exclua clientes com confirmação"><div className="grid gap-4 md:grid-cols-2">{items.length===0?<Empty text="Nenhum cliente cadastrado."/>:items.map(c=><article key={c.id} className="rounded-2xl border bg-white p-5"><UserRound className="h-7 w-7 text-blue-900"/><h3 className="mt-3 text-xl font-black">{c.name}</h3><p className="mt-2 text-sm text-slate-500">{c.email}<br/>{c.phone}<br/>{c.vehicle}</p><button onClick={()=>confirm('Excluir este cliente e seus dados locais?')&&setItems(items.filter(x=>x.id!==c.id))} className="mt-4 rounded-xl bg-red-50 px-4 py-2 text-sm font-black text-red-700"><Trash2 className="mr-1 inline h-4 w-4"/>Excluir cliente</button></article>)}</div></ManagerShell>}

function DocumentsManager({items,setItems,select}:{items:GarageDocument[];setItems:(v:GarageDocument[])=>void;select:(v:GarageDocument)=>void}){const [type,setType]=useState<DocumentType>('Mitsumori');const blank={customer:'',customerAddress:'',vehicleBrand:'',vehicleModel:'',vin:'',plate:'',engine:'',mileage:'',notes:'Este orçamento está aguardando aprovação do cliente.',responsible:'Félix Yamauchi Eduardo'};const[f,setF]=useState(blank);const[lines,setLines]=useState<DocLine[]>([{description:'',quantity:1,unitPrice:0}]);function create(){if(!f.customer)return;const prefix=type==='Mitsumori'?'CNC':type==='Invoice'?'INV':type==='Seikyusho'?'SEI':'REC';const d:GarageDocument={id:id('DOC'),type,number:`${prefix}-${new Date().getFullYear()}${String(new Date().getMonth()+1).padStart(2,'0')}${String(new Date().getDate()).padStart(2,'0')}-${String(items.length+1).padStart(2,'0')}`,date:new Date().toLocaleDateString('pt-BR'),validity:'30 dias',...f,lines};setItems([d,...items]);select(d);setF(blank);setLines([{description:'',quantity:1,unitPrice:0}]);}return <ManagerShell title="Central de Documentos" subtitle="Mitsumori, Invoice, Seikyūsho e Recibo no padrão corporativo Yamauchi"><EditorGrid><EditorCard title="Criar documento"><select className="input" value={type} onChange={e=>setType(e.target.value as DocumentType)}><option>Mitsumori</option><option>Invoice</option><option>Seikyusho</option><option>Recibo</option></select><input className="input" placeholder="Cliente" value={f.customer} onChange={e=>setF({...f,customer:e.target.value})}/><input className="input" placeholder="Endereço do cliente" value={f.customerAddress} onChange={e=>setF({...f,customerAddress:e.target.value})}/><div className="grid grid-cols-2 gap-3"><input className="input" placeholder="Marca" value={f.vehicleBrand} onChange={e=>setF({...f,vehicleBrand:e.target.value})}/><input className="input" placeholder="Modelo" value={f.vehicleModel} onChange={e=>setF({...f,vehicleModel:e.target.value})}/><input className="input" placeholder="VIN / Chassi" value={f.vin} onChange={e=>setF({...f,vin:e.target.value})}/><input className="input" placeholder="Placa" value={f.plate} onChange={e=>setF({...f,plate:e.target.value})}/><input className="input" placeholder="Motor" value={f.engine} onChange={e=>setF({...f,engine:e.target.value})}/><input className="input" placeholder="KM" value={f.mileage} onChange={e=>setF({...f,mileage:e.target.value})}/></div><p className="font-black">Itens / Serviços</p>{lines.map((line,i)=><div key={i} className="grid grid-cols-[1fr_70px_110px_40px] gap-2"><input className="input" placeholder="Descrição" value={line.description} onChange={e=>setLines(lines.map((x,n)=>n===i?{...x,description:e.target.value}:x))}/><input className="input" type="number" value={line.quantity} onChange={e=>setLines(lines.map((x,n)=>n===i?{...x,quantity:Number(e.target.value)}:x))}/><input className="input" type="number" value={line.unitPrice} onChange={e=>setLines(lines.map((x,n)=>n===i?{...x,unitPrice:Number(e.target.value)}:x))}/><button onClick={()=>setLines(lines.filter((_,n)=>n!==i))}><Trash2 className="text-red-600"/></button></div>)}<button onClick={()=>setLines([...lines,{description:'',quantity:1,unitPrice:0}])} className="rounded-xl border py-3 text-sm font-black"><Plus className="mr-1 inline h-4 w-4"/>Adicionar item</button><textarea className="input" value={f.notes} onChange={e=>setF({...f,notes:e.target.value})}/><PrimaryButton onClick={create}>GERAR E IMPRIMIR PDF</PrimaryButton></EditorCard><ListCard items={items} render={(d)=><div key={d.id} className="flex items-center justify-between rounded-2xl border p-4"><div><p className="text-xs font-black text-amber-600">{d.type}</p><p className="font-black">{d.number}</p><p className="text-sm text-slate-500">{d.customer} · {d.date}</p></div><div className="flex gap-2"><button onClick={()=>select(d)} className="rounded-xl bg-blue-950 p-3 text-white"><Printer className="h-4 w-4"/></button><button onClick={()=>confirm('Excluir este documento?')&&setItems(items.filter(x=>x.id!==d.id))} className="rounded-xl bg-red-50 p-3 text-red-700"><Trash2 className="h-4 w-4"/></button></div></div>} /></EditorGrid></ManagerShell>}

function DocumentPrint({document,close}:{document:GarageDocument;close:()=>void}){const subtotal=document.lines.reduce((s,l)=>s+l.quantity*l.unitPrice,0);const tax=Math.round(subtotal*.1);const total=subtotal+tax;const japanese=document.type==='Mitsumori'?'見積書':document.type==='Seikyusho'?'請求書':document.type==='Recibo'?'領収書':'INVOICE';return <div className="fixed inset-0 z-[120] overflow-auto bg-slate-900/80 p-3 print:static print:bg-white print:p-0"><div className="mx-auto mb-3 flex max-w-[1050px] gap-2 print:hidden"><button onClick={close} className="rounded-xl bg-white px-4 py-2 font-black">Fechar</button><button onClick={()=>window.print()} className="rounded-xl bg-amber-400 px-4 py-2 font-black"><Printer className="mr-1 inline h-4 w-4"/>Imprimir / Salvar PDF</button></div><article id="corporate-document" className="mx-auto min-h-[1400px] max-w-[1050px] bg-white text-slate-950 shadow-2xl print:min-h-0 print:max-w-none print:shadow-none"><header className="grid grid-cols-[1.2fr_.8fr] overflow-hidden"><div className="bg-gradient-to-br from-slate-950 to-blue-950 p-8 text-white"><p className="text-4xl font-black text-amber-400">YAMAUCHI GARAGE</p><p className="mt-2 text-xl tracking-[.35em]">AUTO CENTER</p><p className="mt-3 text-2xl font-black">山内ガレージ板金</p></div><div className="border-b-4 border-amber-400 p-7 text-sm"><p><b>Nº DO DOCUMENTO</b><br/>{document.number}</p><p className="mt-4"><b>DATA DE EMISSÃO</b><br/>{document.date}</p><p className="mt-4"><b>VALIDADE</b><br/>{document.validity}</p></div></header><div className="px-7 py-6 text-center"><h1 className="text-5xl font-black">{japanese}</h1><p className="mt-2 text-2xl font-black">{document.type.toUpperCase()}</p><p className="mt-3">Conforme abaixo, apresentamos este documento.</p></div><div className="grid grid-cols-2 gap-5 px-7"><DocBox title="ご見積先 / CLIENTE"><p className="text-2xl font-black">{document.customer}</p><p className="mt-4">{document.customerAddress}</p></DocBox><DocBox title="山内ガレージ板金 / YAMAUCHI GARAGE AUTO CENTER"><p>{shop.address}</p><p className="mt-3">{shop.phone}</p><div className="ml-auto mt-3 w-fit rounded-xl border-4 border-red-500 p-3 text-center font-black text-red-600">山内<br/>ガレージ板金<br/><span className="text-sm">YAMAUCHI GARAGE</span></div></DocBox></div><div className="mx-7 mt-5 overflow-hidden rounded-xl border"><div className="bg-slate-950 px-4 py-3 font-black text-white">車両情報 / DADOS DO VEÍCULO</div><div className="grid grid-cols-6 text-center text-sm"><Cell label="MARCA" value={document.vehicleBrand}/><Cell label="MODELO" value={document.vehicleModel}/><Cell label="CHASSIS / VIN" value={document.vin}/><Cell label="PLACA" value={document.plate}/><Cell label="MOTOR" value={document.engine}/><Cell label="KM" value={document.mileage}/></div></div><div className="mx-7 mt-5 grid grid-cols-[1fr_300px] gap-4"><div className="overflow-hidden rounded-xl border"><div className="bg-slate-950 px-4 py-3 font-black text-white">作業内容 / SERVIÇOS</div><table className="w-full border-collapse text-sm"><thead><tr className="bg-slate-100"><th className="border p-3">No.</th><th className="border p-3 text-left">DESCRIÇÃO</th><th className="border p-3">QTD.</th><th className="border p-3">VALOR UNIT.</th><th className="border p-3">TOTAL</th></tr></thead><tbody>{document.lines.map((l,i)=><tr key={i}><td className="border p-3 text-center">{i+1}</td><td className="border p-3">{l.description}</td><td className="border p-3 text-center">{l.quantity}</td><td className="border p-3 text-right">{yen(l.unitPrice)}</td><td className="border p-3 text-right">{yen(l.quantity*l.unitPrice)}</td></tr>)}</tbody></table></div><div className="overflow-hidden rounded-xl border"><p className="flex justify-between border-b p-4"><span>SUBTOTAL</span><b>{yen(subtotal)}</b></p><p className="flex justify-between border-b p-4"><span>IMPOSTO (10%)</span><b>{yen(tax)}</b></p><div className="bg-slate-950 p-5 text-white"><p>TOTAL GERAL</p><p className="mt-3 text-4xl font-black text-amber-400">{yen(total)}</p></div></div></div><div className="mx-7 mt-5 grid grid-cols-3 gap-4"><DocBox title="備考 / OBSERVAÇÕES"><p className="whitespace-pre-line text-sm">{document.notes}</p></DocBox><DocBox title="お見積人 / ORÇAMENTO POR"><p className="font-black">RESPONSÁVEL:</p><p>{document.responsible}</p><p className="mt-4 font-black">EMPRESA:</p><p>{shop.name}</p><p>{shop.address}</p><p>{shop.phone}</p></DocBox><DocBox title="ご署名欄 / ASSINATURA"><div className="mt-8 border-b"></div><p className="mt-3 text-center text-sm">ASSINATURA</p><div className="ml-auto mt-5 w-fit rounded-xl border-4 border-red-500 p-3 text-center font-black text-red-600">山内<br/>ガレージ板金</div></DocBox></div><footer className="mt-6 grid grid-cols-3 bg-slate-950 p-6 text-center text-white"><div><p className="font-black text-amber-400">1 ANO DE GARANTIA</p></div><div><p className="font-black text-amber-400">ATENDIMENTO EM TODO O JAPÃO</p></div><div><p>YAMAUCHI GARAGE AUTO CENTER</p><p className="font-black text-amber-400">SINCE 2016</p></div></footer></article></div>}
function DocBox({title,children}:{title:string;children:ReactNode}){return <section className="overflow-hidden rounded-xl border"><div className="bg-slate-950 px-4 py-2 font-black text-white">{title}</div><div className="min-h-40 p-5">{children}</div></section>}
function Cell({label,value}:{label:string;value:string}){return <div className="border-r p-3"><p className="text-xs font-black">{label}</p><p className="mt-3 font-bold">{value||'---'}</p></div>}

function ManagerShell({title,subtitle,children}:{title:string;subtitle:string;children:ReactNode}){return <div><SectionTitle kicker="ADMINISTRAÇÃO" title={title} action={subtitle}/>{children}</div>}
function EditorGrid({children}:{children:ReactNode}){return <div className="grid gap-6 xl:grid-cols-[420px_1fr]">{children}</div>}
function EditorCard({title,children}:{title:string;children:ReactNode}){return <div className="h-fit space-y-3 rounded-3xl border bg-white p-5"><h2 className="text-xl font-black"><Plus className="mr-1 inline h-5 w-5"/>{title}</h2>{children}</div>}
function ListCard<T>({items,render}:{items:T[];render:(i:T)=>ReactNode}){return <div className="space-y-3 rounded-3xl border bg-white p-5">{items.length===0?<Empty text="Nenhum item cadastrado."/>:items.map(render)}</div>}
function FileField({label,value,setValue}:{label:string;value:string;setValue:(v:string)=>void}){return <><label className="block cursor-pointer rounded-xl border-2 border-dashed p-4 text-center text-sm font-black text-slate-500"><ImageIcon className="mr-1 inline h-4 w-4"/>{label}<input className="hidden" type="file" accept="image/*" onChange={e=>{const file=e.target.files?.[0];if(file)imageFromFile(file,setValue)}}/></label>{value&&<img src={value} alt="Prévia" className="h-32 w-full rounded-xl object-contain bg-slate-100"/>}</>}
function ContentRow({image,title,subtitle,active,toggle,remove}:{image:string;title:string;subtitle:string;active:boolean;toggle:()=>void;remove:()=>void}){return <div className="flex items-center gap-4"><img src={image} alt={title} className="h-20 w-24 rounded-xl object-cover bg-slate-100"/><div className="min-w-0 flex-1"><p className="truncate font-black">{title}</p><p className="text-sm text-slate-500">{subtitle}</p></div><button onClick={toggle} className={`rounded-xl px-3 py-2 text-xs font-black ${active?'bg-emerald-50 text-emerald-700':'bg-slate-100 text-slate-500'}`}>{active?'Visível':'Oculto'}</button><button onClick={remove} className="rounded-xl bg-red-50 p-3 text-red-700"><Trash2 className="h-4 w-4"/></button></div>}
function PrimaryButton({onClick,children}:{onClick:()=>void;children:ReactNode}){return <button type="button" onClick={onClick} className="w-full rounded-xl bg-blue-950 py-4 font-black text-white">{children}</button>}
function Empty({text}:{text:string}){return <div className="rounded-2xl border-2 border-dashed p-10 text-center text-slate-500"><ClipboardList className="mx-auto mb-3"/><p>{text}</p></div>}
